head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd   = ""; // 조회조건 기업코드

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 화면을 초기화한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00307.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 시점 처리(현재 처리 없음).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name grd_RetiPayAlwnc_oncelldblclick
 * @description 팝업호출 — 기준년월 컬럼 더블클릭 시 퇴직급여충당금 상세 팝업을 오픈한다.
 * @param {Number} rowIndex 더블클릭한 행 인덱스
 * @param {Number} columnIndex 더블클릭한 컬럼 인덱스
 * @param {String} columnId 더블클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.grd_RetiPayAlwnc_oncelldblclick(0, 0, "basYymm");
 */
scwin.grd_RetiPayAlwnc_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        if (columnId === "basYymm") {
            scwin.retiPayAlwncDtlSrchOpen(rowIndex);  // 퇴직급여충당금 상세  팝업 오픈
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00307.grd_RetiPayAlwnc_oncelldblclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name init
 * @description 화면 초기화
 * @returns {void}
 * @hidden N
 * @example scwin.init();
 */
scwin.init = function() {
    scwin.search();
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 * @example scwin.initDs();
 */
scwin.initDs = function() {
    dlt_RetiPayAlwncRes.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {Boolean} 유효성 체크 결과
 * @hidden N
 * @example if (!scwin.chkValid()) { return; }
 */
scwin.chkValid = function() {
    // 필수항목 체크.
    scwin.vKisCd = $p.parent().wfm_header.getWindow().scwin.fn_GetKisCd();
    if (scwin.vKisCd=== "") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name search
 * @description 퇴직급여충당금 조회
 * @returns {void}
 * @hidden N
 * @example scwin.search();
 */
scwin.search = function() {

    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    const ibxKisCd = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue();

    const url = "/api/listing/nice/individual-notes/" + ibxKisCd + "/retirement-benefits";
    $c.sbm.setAction(sbm_dlt_RetiPayAlwnc, url);
    $c.sbm.execute(sbm_dlt_RetiPayAlwnc);
};

/**
 * @method
 * @name retiPayAlwncDtlSrchOpen
 * @description 퇴직급여충당금 상세 팝업
 * @param {Number} pRow 대상 행 인덱스
 * @returns {void}
 * @hidden N
 * @example scwin.retiPayAlwncDtlSrchOpen(0);
 */
scwin.retiPayAlwncDtlSrchOpen = function(pRow) {

    console.log(pRow);
    const url = "/ui/lst/fis/ULDFIS00300_P5.xml";
    const popTitle = "퇴직급여 충담금 검색";

    const opts = {
        id: "ULDFIS00300_P5",
        popupName: popTitle,
        width: 700,
        height: 600,
        frameModal: "top",
    };

    const popData = dlt_RetiPayAlwncRes.getRowJSON(pRow);
    $c.win.openPopup(url, opts, popData);

};

/**
 * @method
 * @name excelDownload
 * @description 엑셀파일다운로드
 * @returns {void}
 * @hidden N
 * @example scwin.excelDownload();
 */
scwin.excelDownload = function() {
    if (dlt_RetiPayAlwncRes.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_RetiPayAlwnc, {fileName: "퇴직급여충당금", type: "8"});
};
